starterCode:
LOAD spatial;

-- Compute the length of each route from its WKT linestring.
-- Return: route_name, length_units ordered by length_units DESC

setup:
CREATE TABLE routes AS SELECT * FROM (VALUES
  (1, 'Route A', 'LINESTRING(0 0, 10 0)'),
  (2, 'Route B', 'LINESTRING(0 0, 5 5)'),
  (3, 'Route C', 'LINESTRING(0 0, 10 0, 10 10)')
) t(route_id, route_name, wkt);

solution:
LOAD spatial;

SELECT route_name,
       ST_Length(ST_GeomFromText(wkt)) AS length_units
FROM routes
ORDER BY length_units DESC;
